function formatControl(id:string,value:number|string){const spec=numericControls[id];if(!spec)return String(value);return (spec.prefix||"")+Number(value).toLocaleString("pt-BR")+(spec.suffix||"")}
function FactorControl({factor,value,selected,onChange,onSelect}:{factor:Factor;value:number|string;selected:boolean;onChange:(v:number|string)=>void;onSelect:()=>void}){const spec=numericControls[factor.id],options=optionControls[factor.id],help=factorHelp[factor.id];return <div className={"factor-control "+factor.color+" "+(selected?"selected":"")} onClick={onSelect}><header><span>{factor.label}</span><button className="factor-help" type="button" aria-label={"Explicar "+factor.label} aria-describedby={"help-"+factor.id} onClick={e=>e.stopPropagation()}>?<span className="factor-tooltip" id={"help-"+factor.id} role="tooltip"><strong>O que controla</strong>{help.meaning}<strong>Efeito ao alterar</strong>{help.effect}</span></button><b>{formatControl(factor.id,value)}</b></header>{spec&&<><input aria-label={factor.label} type="range" min={spec.min} max={spec.max} step={spec.step} value={value} onChange={e=>{onSelect();onChange(+e.target.value)}}/><footer><small>{formatControl(factor.id,spec.min)}</small><small>{formatControl(factor.id,spec.max)}</small></footer></>}{options&&<div className="preset-options">{options.map(x=><button className={value===x?"active":""} onClick={e=>{e.stopPropagation();onSelect();onChange(x)}} key={x}>{x}</button>)}</div>}</div>}
function getLiveLayers(v:Record<string,number|string>){return technicalLayers.map(layer=>{let cells=layer.cells.map(cell=>[...cell]);if(layer.kind==="data")cells[0]=["Mensagem","Compra e pagamento","Devolução","Histórico entregue: "+v.e1];if(layer.kind==="system")cells[1]=["Pagamentos","Devoluções","Motor de risco"];if(layer.kind==="tool")cells[2]=["Emitir reembolso","Enviar explicação","Se o modelo falhar: "+v.t3];if(layer.kind==="model"){cells[0]=[String(v.t1)];cells[1]=[String(v.t2)]}if(layer.kind==="rule"){cells[0]=["Aceitar categoria a partir de "+v.r1+"%","Priorizar após "+v.o1+" min"];cells[1]=["Investigar diferença a partir de "+v.f1+"%","Permitir decisão automática até risco "+v.r2,"Liberar até "+formatControl("f2",v.f2),v.r3+" fontes devem confirmar"];cells[2]=["Taxa retida até "+v.f3+"%","Encaminhar após "+v.o2+" falhas automáticas"]}if(layer.kind==="permission")cells[2]=["Reembolso: escrita limitada","Crédito de cortesia até "+formatControl("e3",v.e3)];if(layer.kind==="human")cells[3]=["Equipe recebe "+v.o3+" casos","Ao transferir, enviar: "+v.e2];return{...layer,cells}})}
function estimateImpact(id:string,value:number|string){
 const optionResults:Record<string,Record<string,string>>={
  e1:{essencial:"A IA recebe mensagem, identificador da compra e estado da devolução.",média:"A IA também recebe os contatos recentes e o histórico desse pagamento.",alta:"A IA recebe o histórico completo de compras, devoluções, disputas e reembolsos."},
  e2:{"transferência simples":"A pessoa recebe o pedido e os dados de identificação.","resumo do caso":"A pessoa também recebe um resumo das consultas e decisões já realizadas.","contexto completo":"A pessoa recebe dados, consultas, regras avaliadas, decisões e falhas anteriores."},
  t1:{"Gemini Flash":"Todas as mensagens novas são classificadas pelo Gemini Flash.","GPT-5 mini":"Todas as mensagens novas são classificadas pelo GPT-5 mini.","Modelo interno":"Todas as mensagens novas são classificadas pelo modelo interno."},
  t2:{"GPT-5 mini":"Todas as divergências são analisadas pelo GPT-5 mini antes das regras finais.","Claude Sonnet":"Todas as divergências são analisadas pelo Claude Sonnet antes das regras finais.","Modelo interno":"Todas as divergências são analisadas pelo modelo interno antes das regras finais."},
  t3:{"sem fallback":"Uma falha do modelo interrompe a automação e registra erro.","modelo interno":"Uma falha do modelo principal aciona o modelo interno.","fila humana":"Uma falha do modelo principal encaminha o atendimento para uma pessoa."}
 };
 if(optionResults[id]?.[String(value)])return optionResults[id][String(value)];
 const n=Number(value);const estimates:Record<string,string>={f1:Math.round(38+(n-5)*6)+" operações exigiriam revisão financeira",f2:Math.max(8,Math.round(68-n/180))+" operações exigiriam aprovação humana",f3:Math.round(n*3.2)+" operações poderiam receber desconto automático",o1:Math.round(60+n*4.8)+" atendimentos teriam a prioridade recalculada",o2:Math.round(18+n*11)+" operações seriam transferidas após esse número de falhas",o3:Math.max(0,140-n)+" operações ficariam aguardando vaga",r1:Math.round((n-70)*5.1)+" operações exigiriam conferência da classificação",r2:Math.round((10-n)*31)+" operações exigiriam decisão humana",r3:Math.round(n*26.5)+" operações aguardariam confirmação dos dados",e3:Math.round(n/7.4)+" operações poderiam receber compensação automática"};return estimates[id]||factors.find(f=>f.id===id)?.impact||"500 operações avaliadas"}
function liveRule(id:string,v:number|string){const rules:Record<string,string>={f1:"Investigar reembolsos cuja diferença seja de "+v+"% ou mais.",f2:"Correções acima de "+formatControl("f2",v)+" precisam de aprovação humana.",f3:"Taxas retidas acima de "+v+"% precisam de revisão humana.",o1:"Atendimentos abertos há "+v+" minutos recebem prioridade na fila.",o2:"Após "+v+" tentativas de aplicar uma solução aprovada falharem, uma pessoa assume o atendimento.",o3:"Depois de "+v+" entradas na fila humana no mesmo período, novos casos aguardam vaga.",r1:"Categorias com nota menor que "+v+"% precisam ser conferidas por uma pessoa.",r2:"Reembolsos com risco acima de "+v+"/10 precisam ser decididos por uma pessoa.",r3:"A decisão espera até "+v+" fontes confirmarem o mesmo dado.",e1:"Todos os atendimentos enviam à IA o conjunto de dados anteriores: "+v+".",e2:"Quando uma pessoa assume, recebe: "+v+".",e3:"Créditos de cortesia acima de "+formatControl("e3",v)+" precisam de aprovação humana.",t1:v+" classifica todas as novas mensagens.",t2:v+" analisa todas as divergências antes das regras finais.",t3:"Se o modelo principal falhar, o sistema aciona "+v+"."};return rules[id]||"Regra atualizada"}
function caseEffect(id:string,value:number|string){const n=Number(value);const effects:Record<string,string>={f1:`A proposta preserva 11% de margem. ${11>=n?"Ela pode continuar para as outras verificações.":"Ela precisa de revisão financeira antes de ser aprovada."}`,f2:n>=7800?"A mensalidade proposta de R$ 7.800 está dentro da permissão do agente; a renegociação pode ser aprovada se também atender às demais regras.":"A mensalidade proposta de R$ 7.800 supera a permissão do agente; uma pessoa do Financeiro precisa aprovar a renegociação.",f3:`A proposta solicita 8% de desconto. ${8<=n?"O agente pode concedê-lo se a proposta for aprovada.":"Uma pessoa precisa autorizar esse desconto."}`,o1:`O pedido está aberto há 14 minutos. ${14>n?`Ele já ultrapassou o tempo de ${n} minutos e recebe prioridade.`:`Ele receberá prioridade em ${n-14} minutos se ainda estiver aberto.`}`,o2:"A proposta ainda não chegou à execução: ela foi encaminhada ao Financeiro antes de qualquer tentativa de alterar o contrato.",o3:"A proposta entra na fila do Financeiro e aguarda uma das vagas disponíveis no período.",r1:`A IA atribuiu nota de 87% à categoria ‘renegociação de plano’. ${87>=n?"O sistema aceita essa categoria sem conferência humana.":"Uma pessoa precisa conferir se o pedido foi categorizado corretamente."}`,r2:`O motor corporativo calculou risco 5/10 usando valor, histórico e alertas de política. ${5<=n?"Esse resultado permite continuar a análise automática.":"Esse resultado exige decisão humana."}`,r3:`CRM e sistema de contratos confirmam os dados da proposta. ${2>=n?"A quantidade de confirmações exigida foi atingida.":"Ainda falta uma fonte confirmar os dados."}`,e1:`A IA recebe o conjunto ${value} de dados anteriores do cliente para interpretar o pedido.`,e2:`Ao assumir a aprovação, o Financeiro recebe ${value}.`,e3:"A proposta não inclui compensação ao cliente; este controle não participa desta decisão.",t1:`${value} identifica a categoria do pedido e extrai os dados da proposta.`,t2:`${value} organiza a análise da proposta antes da aplicação das regras.`,t3:"O modelo principal respondeu corretamente; a rota de falha não participa deste atendimento."};return effects[id]||"A proposta será reavaliada com o valor selecionado."}
function caseOutcome(id:string,value:number|string){const n=Number(value);const titles:Record<string,string>={f1:11>=n?"Margem aprovada":"Revisão financeira necessária",f2:n>=7800?"Pode seguir automaticamente":"Exige aprovação financeira",f3:"Desconto ainda não aplicável",o1:14>n?"Atendimento fora do prazo":"Atendimento dentro do prazo",o2:"Tentativas ainda não iniciadas",o3:"Encaminhado para a fila Financeiro",r1:87>=n?"Classificação aceita":"Validação humana necessária",r2:5<=n?"Risco dentro do limite":"Decisão autônoma bloqueada",r3:2>=n?"Evidências suficientes":"Falta uma fonte concordante",e1:"Contexto preparado para a Entrada",e2:"Handoff humano configurado",e3:"Compensação não executada",t1:"Modelo de classificação definido",t2:"Modelo de decisão definido",t3:"Fallback não acionado"};return{title:titles[id]||"Atendimento reavaliado",detail:caseEffect(id,value)}}
function interventionOutcome(id:string,baseline:number|string,value:number|string){
 const a=Number(baseline),b=Number(value),up=b>a,same=String(baseline)===String(value);
 if(same)return{title:"Regra aplicada",detail:liveRule(id,value)};
 const low=Math.min(a,b),high=Math.max(a,b);
 const outcomes:Record<string,{title:string;detail:string}>={
  f1:{title:up?"Mais casos exigem revisão financeira":"Mais casos podem seguir para execução",detail:up?`Soluções com margem entre ${low}% e ${high-1}% deixam de ser autorizadas e seguem para revisão financeira.`:`Soluções com margem entre ${low}% e ${high-1}% deixam de exigir revisão financeira e podem ser executadas.`},
  f2:{title:up?"Mais casos podem ser aprovados pelo agente":"Mais casos seguem para aprovação humana",detail:up?`Valores entre ${formatControl("f2",low)} e ${formatControl("f2",high)} passam a ficar dentro da autonomia do agente.`:`Valores entre ${formatControl("f2",low)} e ${formatControl("f2",high)} deixam a autonomia do agente e seguem para aprovação humana.`},
  f3:{title:up?"Mais descontos podem ser aplicados pelo agente":"Mais descontos exigem autorização",detail:up?`Descontos entre ${low}% e ${high}% passam a ser executáveis sem autorização adicional.`:`Descontos entre ${low}% e ${high}% passam a exigir autorização.`},
  o1:{title:up?"A prioridade por atraso será acionada mais tarde":"A prioridade por atraso será acionada mais cedo",detail:up?`Atendimentos com ${low} a ${high-1} minutos deixam de ser considerados atrasados pelo SLA.`:`Atendimentos com ${low} a ${high-1} minutos passam a ser considerados atrasados e recebem prioridade.`},
  o2:{title:up?"O sistema tolera mais falhas antes do encaminhamento":"Uma pessoa assume após menos falhas",detail:`Ao registrar ${value} falha${b===1?"":"s"} automática${b===1?"":"s"} consecutiva${b===1?"":"s"}, o sistema interrompe novas tentativas e entrega o caso com o histórico do que falhou.`},
  o3:{title:up?"Mais casos entram na fila humana":"Mais casos ficam aguardando capacidade",detail:up?`A fila humana passa a aceitar até ${value} casos por período; o excedente permanece em espera.`:`Após ${value} casos no período, novos encaminhamentos permanecem em espera.`},
  r1:{title:up?"Mais classificações exigem validação humana":"Mais classificações seguem direto para decisão",detail:up?`Classificações entre ${low}% e ${high-1}% deixam de ser aceitas automaticamente e seguem para validação humana.`:`Classificações entre ${low}% e ${high-1}% deixam de ir para validação humana e seguem para a etapa de decisão.`},
  r2:{title:up?"Mais casos de risco podem ser decididos pelo agente":"Mais casos de risco exigem revisão",detail:up?`Casos com risco entre ${low+1} e ${high} passam a permitir decisão autônoma.`:`Casos com risco entre ${low+1} e ${high} deixam de permitir decisão autônoma e seguem para revisão.`},
  r3:{title:up?"Mais casos aguardam confirmação de dados":"Mais casos podem seguir com as evidências disponíveis",detail:up?`A decisão fica bloqueada até que ${value} fontes confirmem a mesma informação.`:`A decisão pode seguir quando ${value} fonte${b===1?" confirma":"s confirmam"} a informação.`},
  e3:{title:up?"Mais compensações podem ser emitidas pelo agente":"Mais compensações exigem autorização",detail:up?`Compensações entre ${formatControl("e3",low)} e ${formatControl("e3",high)} passam a ser autorizadas automaticamente.`:`Compensações entre ${formatControl("e3",low)} e ${formatControl("e3",high)} passam a exigir autorização.`}
 };
 const optionOutcomes:Record<string,{title:string;detail:string}>={
  e1:{title:"O agente recebe outro nível de contexto",detail:`A classificação passa a utilizar o contexto ${value} do histórico do cliente.`},
  e2:{title:"O conteúdo da transferência foi alterado",detail:`Quando uma pessoa assumir o caso, receberá ${value}.`},
  t1:{title:"A classificação será processada por outro modelo",detail:`Novas entradas serão classificadas por ${value}.`},
  t2:{title:"A decisão será processada por outro modelo",detail:`A análise de evidências e regras será executada por ${value}.`},
  t3:{title:"A rota de falha foi alterada",detail:`Quando o modelo principal não responder, o sistema acionará ${value}.`}
 };
 return outcomes[id]||optionOutcomes[id]||{title:"Regra aplicada",detail:liveRule(id,value)}
}
