function PlayTour({step,setStep,onClose}:{step:number;setStep:(step:number)=>void;onClose:()=>void}){const item=lessonSteps[step];useEffect(()=>{document.querySelector(`[data-lesson="${item.stage}-${item.layer}"]`)?.scrollIntoView({behavior:"smooth",block:"center"})},[item]);return <div className={"lesson-ui "+(("skipped" in item)?"skipped-step":"")} role="dialog" aria-modal="true" aria-label="Explicação guiada do fluxo"><div className="lesson-progress" aria-label={`Passo ${step+1} de ${lessonSteps.length}`}><span style={{width:`${((step+1)/lessonSteps.length)*100}%`}}/></div><aside className="lesson-panel"><header><div><small>MODO AULA · PERCURSO SEQUENCIAL</small><b>{item.eyebrow.split(" · ")[1]}</b></div><button onClick={onClose} aria-label="Sair do modo aula">×</button></header><div className="lesson-stage-mark"><span>{String(step+1).padStart(2,"0")}/{String(lessonSteps.length).padStart(2,"0")}</span><i/><em>{technicalLayers.find(layer=>layer.kind===item.layer)?.name}</em></div><h2>{item.title}</h2><section><small>COMO ACONTECE TECNICAMENTE</small><p>{item.technical}</p></section><footer><small>SAÍDA DESTA ETAPA</small><strong>{item.output}</strong></footer><nav><button onClick={()=>setStep(step-1)} disabled={step===0}>← Voltar</button><div>{lessonSteps.map((_,index)=><i className={index===step?"active":index<step?"done":""} key={index}/>)}</div>{step<lessonSteps.length-1?<button className="next" onClick={()=>setStep(step+1)}>Próximo →</button>:<button className="next" onClick={onClose}>Concluir ✓</button>}</nav></aside></div>}
function FactorDock({factor,value,onClose}:{factor:Factor;value:number|string;onClose:()=>void}){const categorical=Boolean(optionControls[factor.id]);return <div className="factor-dock-ui" role="dialog" aria-modal="false" aria-label={"Explicação de "+factor.label}><section className={"factor-dock simple "+factor.color}><button className="factor-dock-close" onClick={onClose} aria-label="Fechar painel">×</button><div className={"factor-dock-story "+(categorical?"single":"")}>{!categorical&&<article className="factor-case-result"><small>REGRA CONFIGURADA</small><h3>{liveRule(factor.id,value)}</h3></article>}<aside className="factor-operation-impact"><small>{categorical?"O QUE ESSA OPÇÃO INCLUI":"EFEITO NO FLUXO"}</small><strong>{categorical?estimateImpact(factor.id,value):factorGuide[factor.id].when}</strong></aside></div></section></div>}
export default function Home(){const[selected,setSelected]=useState("f2"),[values,setValues]=useState<Record<string,number|string>>(()=>Object.fromEntries(factors.map(f=>[f.id,numericControls[f.id]?.initial??optionControls[f.id]?.[0]??f.value]))),[activeLayer,setActiveLayer]=useState("rule"),[playStep,setPlayStep]=useState<number|null>(null),[factorDock,setFactorDock]=useState(false),[layerFilters,setLayerFilters]=useState<string[]>([]);const lesson=playStep===null?null:lessonSteps[playStep];const active=factors.find(f=>f.id===selected)!;const activeValue=values[active.id];const liveLayers=getLiveLayers(values);const selectFactor=(id:string)=>{setSelected(id);setActiveLayer(factorLayer[id]||"rule");setPlayStep(null);setFactorDock(true)};const selectLayer=(kind:string,stage:number)=>{setActiveLayer(kind);const match=factors.find(f=>f.stage===stage&&factorLayer[f.id]===kind);if(match)setSelected(match.id)};const toggleLayerFilter=(kind:string)=>setLayerFilters(current=>current.includes(kind)?current.filter(item=>item!==kind):[...current,kind]);const stages=[{n:"01",name:"Entrada",work:"Identifica a solicitação",output:"Divergência estruturada"},{n:"02",name:"Investigação",work:"Reconstrói o cálculo e verifica regras",output:"Correção autorizada"},{n:"03",name:"Resolução",work:"Emite o reembolso autorizado",output:"Crédito confirmado"},{n:"04",name:"Destino",work:"Explica, conclui ou envolve uma pessoa",output:"Cliente notificada"}];return <main className={"linear-screen "+(lesson?"lesson-mode":factorDock?"factor-dock-mode":"")}><header className="linear-header"><div className="linear-brand tech-hall-brand"><img src="/tech-hall-logo.svg" alt="Tech Hall"/></div><button className="lesson-launch" onClick={()=>{setFactorDock(false);setPlayStep(0)}}><span>▶</span> Explicar fluxo</button></header><section className="linear-content"><header className="linear-title case-hero"><div className="case-badge case-featured" style={{gridTemplateColumns:"1fr"}}><div><small>DEMONSTRAÇÃO DIDÁTICA · REFERÊNCIA KLARNA</small><b>Divergência de reembolso</b><span>Uma cliente devolveu uma compra de R$ 380, recebeu R$ 260 e solicita a correção dos R$ 120 restantes. O atendimento REF-2041 e sua arquitetura são simulados.</span></div></div></header><section className="flow-section"><header className="flow-section-title"><div><small>ORQUESTRAÇÃO MULTIAGENTE</small><h2>Pipeline de execução por etapa</h2></div></header><div className="flow-axis"><div className="axis-label"><small>ETAPAS</small><b>Fluxo de execução</b></div>{stages.map((s,i)=><article className={(active.stage===i+1?"active-stage ":"")} key={s.n}><div><small className="agent-kicker">{i<3?"AGENTE":"DESTINO"} {s.n}</small><h2>{s.name}</h2><p>{s.work}</p><span>{s.output}</span></div>{i<3&&<i>→</i>}</article>)}</div></section><section className="technical-matrix"><div className="matrix-title"><b>CAMADAS DA ORQUESTRAÇÃO</b><span>O que cada etapa recebe, acessa, utiliza e entrega</span></div><div className="layer-filter" aria-label="Destacar componentes técnicos"><span>DESTACAR COMPONENTES</span><button className={layerFilters.length===0?"active":""} onClick={()=>setLayerFilters([])}>Tudo</button>{technicalLayers.map(layer=><button className={layerFilters.includes(layer.kind)?"active":""} onClick={()=>toggleLayerFilter(layer.kind)} key={layer.kind}><LayerIcon kind={layer.kind}/>{layer.name}</button>)}</div><div className="matrix-head"><span>CAMADA</span>{stages.map(s=><span key={s.n}>{s.n} · {s.name}</span>)}</div>{liveLayers.map(layer=><div className={"matrix-row "+layer.kind+" "+(activeLayer===layer.kind?"active-layer ":"")+(layerFilters.length&&!layerFilters.includes(layer.kind)?"filtered-out":"")} key={layer.name}><header onClick={()=>setActiveLayer(layer.kind)}><LayerIcon kind={layer.kind}/><b>{layer.name}</b></header>{layer.cells.map((cell,index)=><button className={"matrix-cell "+(active.stage===index+1?"active-stage":"")+(lesson?.stage===index+1&&lesson.layer===layer.kind?" lesson-focus":"")} data-lesson={(index+1)+"-"+layer.kind} onClick={()=>selectLayer(layer.kind,index+1)} key={index}>{cell.map(item=><span className="matrix-item" key={item}><LayerIcon kind={itemIconKind(layer.kind,item)}/><b>{item}</b></span>)}</button>)}</div>)}</section><section className="intervention-map"><div className="map-head"><span>RESPONSABILIDADE</span>{stages.map(s=><span key={s.n}>{s.name}</span>)}</div>{["Financeiro","Operações","Risco","Experiência","Tecnologia"].map(role=><Fragment key={role}><div className={"role-row "+(active.role===role?"expanded":"")}><header className={"role-name "+factors.find(f=>f.role===role)?.color}><b>{role}</b><span>{factors.filter(f=>f.role===role).length} fatores</span></header>{stages.map((_,stage)=><div className="factor-cell" key={stage}>{factors.filter(f=>f.role===role&&f.stage===stage+1).map(f=><FactorControl factor={f} value={values[f.id]} selected={selected===f.id} onSelect={()=>selectFactor(f.id)} onChange={value=>setValues(current=>({...current,[f.id]:value}))} key={f.id}/>)}</div>)}</div></Fragment>)}</section></section>{factorDock&&!lesson&&<FactorDock factor={active} value={activeValue} onClose={()=>setFactorDock(false)}/>} {lesson&&playStep!==null&&<PlayTour step={playStep} setStep={setPlayStep} onClose={()=>setPlayStep(null)}/>}</main>}

function LegacyHome(){
 const[selected,setSelected]=useState("decisao"),[running,setRunning]=useState(false),[tab,setTab]=useState("execution");
 const active=useMemo(()=>agents.find(a=>a.id===selected)??agents[1],[selected]);
 return <main className="system">
  <header className="system-header"><div className="product"><span>O</span><b>ORQUESTRA</b></div><div className="session-data"><small>SESSÃO</small><b>ORQ-203</b><em>Em demonstração</em></div><div className="session-data"><small>FLUXO ATIVO</small><b>Atendimento ao cliente</b><em>Baseline · 500 operações</em></div><div className="header-actions"><button>Participantes <strong>5</strong></button><button className="facilitator">Facilitador · FR</button></div></header>
  <aside className="system-nav"><nav><small>CONTROLE DA SESSÃO</small>{[["execution","01","Execução de caso"],["architecture","02","Arquitetura do fluxo"],["cases","03","Base de operações"],["roles","04","Configuração dos papéis"],["process","05","Reprocessamento"],["compare","06","Comparação e replay"]].map(x=><button key={x[0]} className={tab===x[0]?"active":""} onClick={()=>setTab(x[0])}><span>{x[1]}</span>{x[2]}</button>)}</nav><section className="room-state"><small>ESTADO DA SESSÃO</small><dl><dt>Fase</dt><dd>Demonstração</dd><dt>Configuração</dt><dd>Baseline</dd><dt>Casos processados</dt><dd>500</dd><dt>Participantes prontos</dt><dd>0 de 5</dd></dl></section></aside>
  <section className="system-content">
   {tab==="execution"&&<>
   <header className="content-header"><div><small>EXECUÇÃO CONTROLADA</small><h1>Caso ATD-217</h1><p>Troca de plano · Cliente empresarial · R$ 7.800 · Risco 5/10</p></div><div className="case-controls"><label>OPERAÇÃO<select defaultValue="217"><option value="217">ATD-217 · acima da alçada</option><option value="118">ATD-118 · execução automática</option><option value="304">ATD-304 · fontes divergentes</option></select></label><button onClick={()=>{setRunning(false);requestAnimationFrame(()=>setRunning(true))}}>Executar caso</button></div></header>
   <section className="case-strip"><div><small>VALOR</small><b>R$ 7.800</b></div><div><small>CONFIANÇA</small><b>87%</b></div><div><small>RISCO</small><b>5 / 10</b></div><div><small>MARGEM</small><b>11%</b></div><div><small>FONTES</small><b>2 concordantes</b></div><div className="case-result"><small>DESTINO CALCULADO</small><b>Revisão humana</b></div></section>
   <section className="orchestration-panel"><header><div><small>MAPA DA ORQUESTRAÇÃO</small><h2>Componentes acionados por este caso</h2></div><div className="legend"><span><i className="agent-key"/> Agente</span><span><i className="system-key"/> Sistema</span><span><i className="rule-key"/> Regra</span><span><i className="human-key"/> Pessoa</span></div></header><div className={`orchestration-map ${running?"running":""}`}><div className="input-node"><small>ENTRADA</small><b>Solicitação</b><span>WhatsApp</span></div>{agents.map((agent,index)=><div className="agent-path" key={agent.id}><div className="path"><i/></div><button className={`agent-node ${selected===agent.id?"selected":""}`} onClick={()=>setSelected(agent.id)}><small>AGENTE {index+1}</small><b>{agent.name}</b><span>{agent.responsibility}</span><footer><em>{agent.consults}</em><em>{agent.rule}</em></footer></button></div>)}<div className="agent-path"><div className="path"><i/></div><div className="human-node"><small>ESCALONAMENTO</small><b>Analista financeiro</b><span>Valor acima de R$ 5.000</span></div></div></div></section>
   <section className="detail-grid"><article className="agent-detail"><header><div><small>AGENTE SELECIONADO</small><h2>Agente de {active.name}</h2></div><span>{active.model}</span></header><div className="work-contract"><div><small>RECEBE</small><b>{active.receives}</b></div><i>→</i><div><small>CONSULTA</small><b>{active.consults}</b></div><i>→</i><div><small>APLICA</small><b>{active.rule}</b></div><i>→</i><div><small>ENTREGA</small><b>{active.produces}</b></div></div><section className="agent-config"><span><small>RESPONSABILIDADE</small>{active.responsibility}</span><span><small>MODELO DE IA</small>{active.model}</span><span><small>PERMISSÃO</small>Leitura de políticas; decisão dentro da alçada</span><span><small>ESCALONAMENTO</small>Encaminha quando uma regra exige julgamento humano</span></section></article><article className="decision-detail"><header><small>DECISÃO DESTE CASO</small><h2>Regras que determinaram o destino</h2></header><div className="rule-check pass"><span>✓</span><div><b>Confiança mínima</b><small>87% ≥ 85% · atendida</small></div></div><div className="rule-check blocked"><span>!</span><div><b>Autonomia financeira</b><small>R$ 7.800 &gt; R$ 5.000 · revisão exigida</small></div></div><div className="rule-check pass"><span>✓</span><div><b>Risco máximo</b><small>5 ≤ 7 · atendida</small></div></div><footer><b>Regra determinante</b><span>A política financeira encaminhou o caso para revisão.</span></footer></article></section>
   <section className="execution-log"><header><div><small>TRILHA DA EXECUÇÃO</small><h2>Eventos registrados</h2></div><span>6 eventos · 2,8 segundos</span></header><div className="log-head"><span>Tempo</span><span>Componente</span><span>Ação</span><span>Resultado</span></div>{execution.map(row=><div className="log-row" key={row.time}><code>{row.time}</code><b>{row.component}</b><span>{row.event}</span><strong>{row.output}</strong></div>)}</section>
   </>}
   {tab==="architecture"&&<Architecture selected={selected} setSelected={setSelected}/>} 
   {tab==="cases"&&<Cases/>}
   {tab==="roles"&&<Roles/>}
   {tab==="process"&&<Reprocessing setTab={setTab}/>} 
   {tab==="compare"&&<Comparison/>}
  </section>
 </main>
}

function PageTitle({kicker,title,detail,action}:{kicker:string;title:string;detail:string;action?:React.ReactNode}){return <header className="content-header"><div><small>{kicker}</small><h1>{title}</h1><p>{detail}</p></div>{action}</header>}

function Architecture({selected,setSelected}:{selected:string;setSelected:(id:string)=>void}){const active=agents.find(a=>a.id===selected)??agents[0];return <><PageTitle kicker="CONFIGURAÇÃO ATIVA · BASELINE" title="Arquitetura do fluxo" detail="Agentes, sistemas, regras, permissões e caminhos humanos utilizados na operação."/><div className="architecture-grid"><section className="architecture-canvas"><div className="arch-lane"><small>CANAL</small><article><b>WhatsApp</b><span>Solicitações digitais</span></article></div><div className="arch-lane"><small>ORQUESTRADOR</small><article><b>Controle de execução</b><span>Estado · roteamento · auditoria</span></article></div><div className="arch-lane agent-lane"><small>AGENTES</small>{agents.map(a=><button className={selected===a.id?"selected":""} onClick={()=>setSelected(a.id)} key={a.id}><b>{a.name}</b><span>{a.responsibility}</span></button>)}</div><div className="arch-lane"><small>SISTEMAS CORPORATIVOS</small>{["CRM","Políticas","Pricing","Catálogo"].map(x=><article key={x}><b>{x}</b><span>Leitura autorizada</span></article>)}</div><div className="arch-lane"><small>DESTINOS</small><article><b>Execução automática</b><span>Ação dentro da alçada</span></article><article><b>Fila humana</b><span>Julgamento especializado</span></article></div></section><aside className="architecture-inspector"><header><small>AGENTE SELECIONADO</small><h2>Agente de {active.name}</h2></header><dl><dt>Responsabilidade</dt><dd>{active.responsibility}</dd><dt>Entrada</dt><dd>{active.receives}</dd><dt>Modelo</dt><dd>{active.model}</dd><dt>Fonte</dt><dd>{active.consults}</dd><dt>Regra principal</dt><dd>{active.rule}</dd><dt>Saída</dt><dd>{active.produces}</dd><dt>Permissão</dt><dd>Leitura; execução condicionada</dd><dt>Fallback</dt><dd>Fila humana de atendimento</dd></dl></aside></div></>}

const sampleCases=Array.from({length:18},(_,i)=>({id:201+i,type:["Troca de plano","Cancelamento","Contestação","Compensação"][i%4],value:1900+((i*937)%9200),risk:1+((i*3)%10),confidence:74+((i*7)%24),route:i%3===0?"Revisão humana":"Automático",reason:i%3===0?"Alçada financeira":"Regras atendidas"}));
function Cases(){const[filter,setFilter]=useState("todos");const rows=sampleCases.filter(c=>filter==="todos"||c.route===filter);return <><PageTitle kicker="BASE SINTÉTICA FIXA" title="500 operações do cenário" detail="A mesma população é utilizada no baseline e no reprocessamento." action={<div className="case-filters"><button className={filter==="todos"?"active":""} onClick={()=>setFilter("todos")}>Todos</button><button className={filter==="Automático"?"active":""} onClick={()=>setFilter("Automático")}>Automáticos</button><button className={filter==="Revisão humana"?"active":""} onClick={()=>setFilter("Revisão humana")}>Revisão humana</button></div>}/><section className="dataset-summary"><span><small>REGISTROS</small><b>500</b></span><span><small>ORDINÁRIOS</small><b>356</b></span><span><small>PRÓXIMOS A LIMITES</small><b>92</b></span><span><small>EXCEÇÕES</small><b>52</b></span></section><section className="data-table"><div className="data-head"><span>Caso</span><span>Solicitação</span><span>Valor</span><span>Risco</span><span>Confiança</span><span>Trajetória</span><span>Regra determinante</span></div>{rows.map(c=><button key={c.id}><b>ATD-{c.id}</b><span>{c.type}</span><span>R$ {c.value.toLocaleString("pt-BR")}</span><span>{c.risk}/10</span><span>{c.confidence}%</span><strong>{c.route}</strong><em>{c.reason}</em></button>)}</section></>}

const roles=[{name:"Financeiro",person:"Mariana Costa",controls:"Margem, desconto e exposição financeira",status:"pronto"},{name:"Operações",person:"André Lima",controls:"SLA, fila humana e concorrência",status:"editando"},{name:"Risco / Compliance",person:"Clara Nunes",controls:"Confiança, risco e fontes exigidas",status:"pronto"},{name:"Experiência",person:"Beatriz Rocha",controls:"Personalização, continuidade e transferência",status:"editando"},{name:"Tecnologia",person:"Rafael Alves",controls:"Modelos, fontes, fallback e chamadas",status:"aguardando"}];
function Roles(){const[role,setRole]=useState(0);return <><PageTitle kicker="MISSÃO LIBERADA" title="Configuração dos papéis" detail="Reduzir o tempo médio em 30% preservando margem e risco."/><div className="roles-layout"><section className="role-list">{roles.map((r,i)=><button className={role===i?"selected":""} onClick={()=>setRole(i)} key={r.name}><i>{r.name.slice(0,2).toUpperCase()}</i><span><b>{r.name}</b><small>{r.person}</small></span><em className={r.status}>{r.status}</em></button>)}</section><section className="role-cockpit"><header><div><small>COCKPIT · {roles[role].name.toUpperCase()}</small><h2>{roles[role].controls}</h2></div><span>{roles[role].person}</span></header><div className="parameter"><label>Autonomia financeira <small>Baseline: R$ 5.000</small></label><b>R$ 8.000</b><input type="range" min="2500" max="12000" defaultValue="8000"/></div><div className="parameter"><label>Margem mínima <small>Baseline: 10%</small></label><b>11%</b><input type="range" min="5" max="18" defaultValue="11"/></div><div className="parameter-impact"><span><small>OPERAÇÕES AFETADAS</small><b>31 de 500</b></span><span><small>MUDAM DE TRAJETÓRIA</small><b>24</b></span><span><small>CONTIDAS POR OUTRA REGRA</small><b>7</b></span></div><footer><span>Alterações salvas para a configuração candidata</span><button>Finalizar configuração</button></footer></section></div></>}

function Reprocessing({setTab}:{setTab:(tab:string)=>void}){const[done,setDone]=useState(false);return <><PageTitle kicker="CONFIGURAÇÃO CANDIDATA" title="Reprocessamento da operação" detail="As novas regras serão aplicadas aos mesmos 500 registros do baseline."/><section className="process-status"><div><small>BASE DE ENTRADA</small><b>500 operações</b><span>Identificadores e características preservados</span></div><i>→</i><div><small>CONFIGURAÇÃO</small><b>Candidata v13</b><span>9 parâmetros alterados por 5 papéis</span></div><i>→</i><div><small>SAÍDA</small><b>{done?"500 processadas":"Aguardando execução"}</b><span>{done?"47 trajetórias modificadas":"Nenhum resultado calculado"}</span></div></section><section className="process-checks"><header><h2>Validações anteriores à execução</h2></header>{["Cinco papéis finalizaram suas configurações","Base de 500 operações preservada","Regras conflitantes identificadas","Versão candidata registrada para auditoria"].map(x=><p key={x}><span>✓</span>{x}</p>)}<button onClick={()=>setDone(true)}>{done?"Reprocessamento concluído":"Reprocessar 500 operações"}</button>{done&&<button className="secondary" onClick={()=>setTab("compare")}>Abrir comparação →</button>}</section></>}

function Comparison(){const[selected,setSelected]=useState(217);return <><PageTitle kicker="BASELINE × CONFIGURAÇÃO CANDIDATA" title="Comparação operacional" detail="500 registros processados nas duas configurações."/><section className="result-summary"><span><small>MANTIVERAM TRAJETÓRIA</small><b>453</b></span><span><small>MUDARAM DE TRAJETÓRIA</small><b>47</b></span><span><small>SAÍRAM DA REVISÃO HUMANA</small><b>24</b></span><span><small>RECEBERAM NOVA VALIDAÇÃO</small><b>9</b></span></section><section className="metric-compare"><div><span>Indicador</span><span>Baseline</span><span>Nova configuração</span><span>Variação</span></div>{[["Automação","78%","84%","+6 p.p."],["Revisão humana","14%","10%","−4 p.p."],["SLA cumprido","91%","95%","+4 p.p."],["Tempo médio","4m12s","3m01s","−28%"],["Margem média","12,8%","11,7%","−1,1 p.p."],["Custo operacional","R$ 3.420","R$ 2.910","−15%"]].map(r=><p key={r[0]}><b>{r[0]}</b><span>{r[1]}</span><strong>{r[2]}</strong><em>{r[3]}</em></p>)}</section><section className="replay-panel"><header><div><small>REPLAY DE OPERAÇÃO</small><h2>Caso ATD-{selected}</h2></div><select value={selected} onChange={e=>setSelected(+e.target.value)}><option value="217">ATD-217 · autonomia financeira</option><option value="304">ATD-304 · conflito entre regras</option><option value="118">ATD-118 · maior redução de tempo</option></select></header><div><article><small>BASELINE</small><p>Entrada → classificação → decisão → <b>limite de R$ 5.000</b> → revisão humana</p><span>18 min · R$ 14,20</span></article><article className="candidate"><small>NOVA CONFIGURAÇÃO</small><p>Entrada → classificação → decisão → <b>autonomia de R$ 8.000</b> → execução automática</p><span>1m40s · R$ 2,80</span></article></div><footer><b>Decisão que provocou a mudança</b><span>Financeiro elevou a autonomia de R$ 5.000 para R$ 8.000. Risco, confiança e margem permitiram a execução.</span></footer></section></>}
